PATH = '/real-estate/cavallo-estates/'
OFFICIAL = 'https://www.treasurehill.com/communities/cavallo/'
GREYBROOK = 'https://greybrook.com/coming-soon-cavallo-estates-luxury-homes-in-the-village-of-nobleton/'
