def link(url, en, fr, cls=''):
    return f'<a class="{cls}" href="{url}">{t(en,fr)}</a>'

def teaser():
    return '<section class="wrap cavallo-teaser"><div><p class="eyebrow">'+t('NEW HOMES IN NOBLETON','MAISONS NEUVES À NOBLETON')+'</p><h2>Cavallo Estates</h2><p>'+t('Detached homes and bungalows by Treasure Hill. Explore the community and ask Katerina about the latest release.','Maisons individuelles et bungalows de Treasure Hill. Découvrez la communauté et renseignez-vous auprès de Katerina sur la dernière phase.')+'</p></div>'+link(PATH,'Explore Cavallo Estates','Découvrir Cavallo Estates','button')+'</section>'

def collections():
    # Published catalogue figures include the finished basement area.
    homes = [
        ('The Manor', t('Two-storey home', 'Maison à deux étages'), 32, 2, 6, '2,820–3,735', '2 820–3 735'),
        ('The Atessa', t('Bungalow', 'Bungalow'), 32, 2, 5, '1,845–2,145', '1 845–2 145'),
        ('The Westport', t('Two-storey home', 'Maison à deux étages'), 50, 3, 6, '3,850–5,665', '3 850–5 665'),
        ('The Waterford', t('Bungalow with loft options', 'Bungalow avec options de mezzanine'), 50, 3, 4, '3,240–4,468', '3 240–4 468'),
        ('The Worthington', t('Bungalow and two-storey designs', 'Bungalow et modèles à deux étages'), 62, None, 4, '4,005–5,380', '4 005–5 380'),
    ]
    cards = []
    for name, layout, width, garage, count, area, area_fr in homes:
        details = [
            (t('Lot width', 'Largeur du terrain'), t(f'{width} ft', f'{width} pi')),
            (t('Garage', 'Garage'), t(f'{garage} cars', f'{garage} voitures') if garage else t('Varies by plan', 'Selon le plan')),
            (t('Floor plans', 'Plans'), str(count)),
            (t('Total area', 'Superficie totale'), t(f'{area} sq. ft.', f'{area_fr} pi²')),
        ]
        facts = ''.join(f'<div><dt>{label}</dt><dd>{value}</dd></div>' for label, value in details)
        cards.append(f'<article><h3>{t(name, name)}</h3><p>{layout}</p><dl>{facts}</dl></article>')
    return '<div class="cavallo-home-grid">'+''.join(cards)+'</div>'

def questions():
    return [
      (t('What is Cavallo Estates?','Qu’est-ce que Cavallo Estates?'),t('Cavallo Estates is Treasure Hill’s new detached-home community at Highway 27 and Fairmont Ridge Trail in Nobleton, King Township. Bungalows and two- and three-car garage options are part of the announced offering.','Cavallo Estates est une nouvelle communauté de maisons individuelles de Treasure Hill, au croisement de la route 27 et de Fairmont Ridge Trail, à Nobleton, dans le canton de King. L’offre annoncée comprend des bungalows et des garages pour deux ou trois voitures.')),
      (t('What is the advertised starting price?','Quel est le prix de départ annoncé?'),t('Treasure Hill advertises a starting price of $999,900, checked November 19, 2026. Ask for the current written price list and confirm the selected home, lot premiums, taxes, rebate assumptions, upgrades and closing adjustments. The headline price is not a complete purchase-cost estimate.','Treasure Hill annonce un prix de départ de 999 900 $, vérifié le 19 novembre 2026. Demandez la liste de prix écrite à jour et confirmez la maison choisie, les primes de terrain, les taxes, les hypothèses de remboursement, les améliorations et les ajustements de clôture. Le prix annoncé ne représente pas le coût total d’achat.')),
      (t('When are closings expected?','Quand les clôtures sont-elles prévues?'),t('CavalloNobleton.com reports that closings could begin in spring 2028. Katerina’s broker-presentation notes indicate summer 2028. Ask Treasure Hill for the written closing dates for your home and lot.','CavalloNobleton.com indique que les premières clôtures pourraient avoir lieu au printemps 2028. Les notes de Katerina sur la présentation aux courtiers évoquent l’été 2028. Demandez à Treasure Hill les dates de clôture écrites pour la maison et le terrain choisis.')),
      (t('Can I see floor plans and the deposit schedule?','Puis-je consulter les plans et le calendrier des dépôts?'),t('Ask Katerina for the latest builder-issued package for the home type you are considering. This guide does not publish a model-by-model price list, deposit schedule or live lot inventory. Availability must be confirmed for the current release.','Demandez à Katerina la documentation la plus récente du constructeur pour le type de maison qui vous intéresse. Ce guide ne publie ni prix par modèle, ni calendrier des dépôts, ni inventaire des terrains en temps réel. La disponibilité doit être confirmée pour la phase en cours.')),
      (t('Is this the builder’s website?','S’agit-il du site du constructeur?'),t('No. Nobleton.ca is an independent community guide. This page connects buyers with Ekaterina (Katerina) Ottchenach of HomeLife Frontier Realty Inc., Brokerage. It does not imply builder representation, exclusive allocations or priority access.','Non. Nobleton.ca est un guide communautaire indépendant. Cette page met les acheteurs en contact avec Ekaterina (Katerina) Ottchenach, de HomeLife Frontier Realty Inc., Brokerage. Elle n’implique aucune représentation du constructeur, attribution exclusive ou priorité d’accès.')),
    ]

def structured_data(base):
    return [
      {'@type':'Article','@id':base+PATH+'#article','headline':t('Cavallo Estates: new detached homes in Nobleton','Cavallo Estates : maisons individuelles neuves à Nobleton'),'datePublished':'2026-11-19','dateModified':'2026-11-19','inLanguage':'en-CA','image':base+PHOTO,'author':{'@type':'Person','name':'Ekaterina Ottchenach','url':base+'/real-estate/'},'publisher':{'@id':base+'/#publisher'},'mainEntityOfPage':{'@id':base+PATH+'#webpage'}},
      {'@type':'FAQPage','@id':base+PATH+'#faq','inLanguage':'en-CA','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in questions()]}
    ]

