    t('Pond and autumn trees at Nobleton Lakes, photographed in 2006','Étang et arbres d’automne à Nobleton Lakes, photographiés en 2006')
    body+='<section class="wrap cavallo-facts" aria-label="'+t('Cavallo project snapshot','Aperçu du projet Cavallo')+'"><div><span>'+t('Builder-advertised from','Prix annoncé à partir de')+'</span><strong>'+t('$999,900*','999 900 $*')+'</strong></div><div><span>'+t('Home options','Types de maisons')+'</span><strong>'+t('Bungalows & two-storeys','Bungalows et maisons à deux étages')+'</strong></div><div><span>'+t('Garage choices','Choix de garages')+'</span><strong>'+t('2–3 cars','2–3 voitures')+'</strong></div><div><span>'+t('Reported closing year','Année de clôture annoncée')+'</span><strong>'+t('2028*','2028*')+'</strong></div></section>'
