    body+='<nav class="wrap cavallo-jump" aria-label="'+t('Cavallo page sections','Sections de la page Cavallo')+'">'+''.join(link(url,en,fr) for url,en,fr in [('#homes','The homes','Les maisons'),('#village','Life in Nobleton','La vie à Nobleton'),('#broker-story','Broker presentation','Présentation aux courtiers'),('#questions','Your questions','Vos questions'),('#inquire','Contact Katerina','Contacter Katerina')])+'</nav>'
    body+='<section id="homes" class="wrap cavallo-section"><div class="cavallo-heading"><div>'+h('Compare the five home collections','Comparez les cinq collections de maisons')+'</div>'+p('The published catalogue shows 25 floor plans ranging from 1,845 to 5,665 sq. ft. The total area shown includes finished basement space. Check the builder’s floor plan for the model and elevation you choose.','Le catalogue publié présente 25 plans de 1 845 à 5 665 pi². La superficie totale indiquée comprend le sous-sol aménagé. Consultez le plan du constructeur pour le modèle et la façade choisis.')+'</div>'+collections()
