    body+='<section id="questions" class="wrap cavallo-section cavallo-faq"><div><p class="eyebrow">'+t('CLEAR ANSWERS','DES RÉPONSES CLAIRES')+'</p>'+h('Cavallo, at a glance.','Cavallo, en bref.')+'</div><div>'+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in questions())+'</div></section>'
